type Screen = 'auth' | 'reset-password' | 'home' | 'character' | 'play' | 'intel' | 'packs' | 'builder' | 'settings' | 'store';
const uid = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, token => { const value = Math.random() * 16 | 0; return (token === 'x' ? value : (value & 0x3 | 0x8)).toString(16); });

function Button({ label, onPress, kind = 'primary', icon, disabled = false }: { label: string; onPress: () => void; kind?: 'primary' | 'ghost' | 'danger'; icon?: keyof typeof Ionicons.glyphMap; disabled?: boolean }) {
  return <Pressable accessibilityRole="button" accessibilityLabel={label} disabled={disabled} onPress={onPress} style={({ pressed }) => [s.button, kind === 'ghost' && s.buttonGhost, kind === 'danger' && s.buttonDanger, (pressed || disabled) && { opacity: .65 }]}>
    {icon && <Ionicons name={icon} size={17} color={kind === 'ghost' ? C.parchment : C.ink} />}<Text style={[s.buttonText, kind === 'ghost' && { color: C.parchment }]}>{label}</Text>
  </Pressable>;
}

function ConfirmDialog({ visible, title, body, confirmLabel, danger = false, onCancel, onConfirm }: { visible: boolean; title: string; body: string; confirmLabel: string; danger?: boolean; onCancel: () => void; onConfirm: () => void }) {
  return <Modal visible={visible} transparent animationType="fade" onRequestClose={onCancel}><View style={s.modalBackdrop}><Pressable accessibilityLabel="Close confirmation" style={StyleSheet.absoluteFill} onPress={onCancel} /><View accessibilityRole="alert" style={s.modalCard}><View style={[s.modalIcon, danger && { borderColor: C.red }]}><Ionicons name={danger ? 'warning-outline' : 'sparkles-outline'} size={28} color={danger ? '#E28B84' : C.gold} /></View><Text style={s.modalTitle}>{title}</Text><Text style={s.modalBody}>{body}</Text><View style={s.modalActions}><Button label="Cancel" kind="ghost" onPress={onCancel} /><Button label={confirmLabel} kind={danger ? 'danger' : 'primary'} onPress={onConfirm} /></View></View></View></Modal>;
}

function AccountDeleteDialog({ visible, password, error, deleting, onPasswordChange, onCancel, onConfirm }: { visible: boolean; password: string; error: string; deleting: boolean; onPasswordChange: (value: string) => void; onCancel: () => void; onConfirm: () => void }) {
  return <Modal visible={visible} transparent animationType="fade" onRequestClose={onCancel}><View style={s.modalBackdrop}><View accessibilityRole="alert" style={[s.modalCard, s.storyErrorCard]}><View style={[s.modalIcon, { borderColor: C.red, backgroundColor: '#281716' }]}><Ionicons name="warning-outline" size={30} color="#F19A92" /></View><Text style={s.modalTitle}>Permanently delete your account?</Text><Text style={s.modalBody}>Your account, campaigns, characters, private worlds, story history, and remaining turns will be deleted from every device. This cannot be undone.</Text><View style={[s.authInputWrap, { width: '100%' }]}><Ionicons name="lock-closed-outline" size={18} color={C.muted} /><TextInput value={password} onChangeText={onPasswordChange} placeholder="Enter your current password" placeholderTextColor="#666" secureTextEntry autoCapitalize="none" autoComplete="current-password" style={s.authInput} accessibilityLabel="Current password" onSubmitEditing={onConfirm} /></View>{error ? <View style={s.authErrorRow}><Ionicons name="alert-circle-outline" size={16} color="#E28B84" /><Text style={s.error}>{error}</Text></View> : null}<View style={s.modalActions}><Button label="Cancel" kind="ghost" onPress={onCancel} /><Button label={deleting ? 'Deleting…' : 'Delete my account'} kind="danger" disabled={deleting || password.length < 8} onPress={onConfirm} /></View></View></View></Modal>;
}

function StoryErrorDialog({ error, campaignId, onClose }: { error: string; campaignId: string; onClose: () => void }) {
  const supportEmail = process.env.EXPO_PUBLIC_SUPPORT_EMAIL || 'support@stablecrown.com';
  const contactSupport = async () => {
    const subject = encodeURIComponent('Sable Crown story turn failed');
    const body = encodeURIComponent(`Hello Sable Crown Support,\n\nA story turn failed and no turn was charged.\n\nCampaign: ${campaignId}\nTime: ${new Date().toISOString()}\nError: ${error}\n\nPlease help me investigate this problem.`);
    try { await Linking.openURL(`mailto:${supportEmail}?subject=${subject}&body=${body}`); }
    catch { Alert.alert('Could not open email', `Please contact ${supportEmail} and include campaign ${campaignId}.`); }
  };
  return <Modal visible={!!error} transparent animationType="fade" onRequestClose={onClose}><View style={s.modalBackdrop}><View accessibilityRole="alert" style={[s.modalCard, s.storyErrorCard]}><View style={[s.modalIcon, { borderColor: C.red, backgroundColor: '#281716' }]}><Ionicons name="warning-outline" size={30} color="#F19A92" /></View><Text style={s.modalTitle}>The story could not advance</Text><Text style={s.modalBody}>{error}</Text><View style={s.errorAssurance}><Ionicons name="shield-checkmark-outline" size={17} color={C.green} /><Text style={s.errorAssuranceText}>Your campaign is safe and no story turn was charged.</Text></View><View style={s.modalActions}><Button label="Close" kind="ghost" onPress={onClose} /><Button label="Contact support" icon="mail-outline" onPress={contactSupport} /></View><Text style={s.errorReference}>REFERENCE · {campaignId.slice(0, 8).toUpperCase()}</Text></View></View></Modal>;
}

function CampaignCreateErrorDialog({ error, onClose }: { error: string; onClose: () => void }) {
  const supportEmail = process.env.EXPO_PUBLIC_SUPPORT_EMAIL || 'support@stablecrown.com';
  const contactSupport = async () => {
    const subject = encodeURIComponent('Sable Crown campaign creation failed');
    const body = encodeURIComponent(`Hello Sable Crown Support,\n\nMy campaign could not be created.\n\nTime: ${new Date().toISOString()}\nError: ${error}\n\nPlease help me investigate this problem.`);
    try { await Linking.openURL(`mailto:${supportEmail}?subject=${subject}&body=${body}`); }
    catch { Alert.alert('Could not open email', `Please contact ${supportEmail}.`); }
  };
  return <Modal visible={!!error} transparent animationType="fade" onRequestClose={onClose}><View style={s.modalBackdrop}><View accessibilityRole="alert" style={[s.modalCard, s.storyErrorCard]}><View style={[s.modalIcon, { borderColor: C.red, backgroundColor: '#281716' }]}><Ionicons name="warning-outline" size={30} color="#F19A92" /></View><Text style={s.modalTitle}>Campaign could not be created</Text><Text style={s.modalBody}>{error}</Text><View style={s.errorAssurance}><Ionicons name="shield-checkmark-outline" size={17} color={C.green} /><Text style={s.errorAssuranceText}>No campaign was saved and no story turns were charged.</Text></View><View style={s.modalActions}><Button label="Close" kind="ghost" onPress={onClose} /><Button label="Contact support" icon="mail-outline" onPress={contactSupport} /></View><Text style={s.errorReference}>{supportEmail.toUpperCase()}</Text></View></View></Modal>;
}

function WorldDeleteErrorDialog({ error, onClose }: { error: string; onClose: () => void }) {
  return <Modal visible={!!error} transparent animationType="fade" onRequestClose={onClose}><View style={s.modalBackdrop}><View accessibilityRole="alert" style={[s.modalCard, s.storyErrorCard]}><View style={[s.modalIcon, { borderColor: C.red, backgroundColor: '#281716' }]}><Ionicons name="warning-outline" size={30} color="#F19A92" /></View><Text style={s.modalTitle}>World cannot be deleted</Text><Text style={s.modalBody}>{error}</Text><View style={s.errorAssurance}><Ionicons name="shield-checkmark-outline" size={17} color={C.green} /><Text style={s.errorAssuranceText}>The world and its campaigns have not been changed.</Text></View><View style={s.modalActions}><Button label="Close" kind="ghost" onPress={onClose} /></View></View></View></Modal>;
}

function Tag({ children }: { children: string }) { return <View style={s.tag}><Text style={s.tagText}>{children}</Text></View> }
function SectionTitle({ eyebrow, title, copy }: { eyebrow?: string; title: string; copy?: string }) { return <View style={{ gap: 5 }}>{eyebrow && <Text style={s.eyebrow}>{eyebrow}</Text>}<Text style={s.h2}>{title}</Text>{copy && <Text style={s.copy}>{copy}</Text>}</View> }

function Auth({ onEnter }: { onEnter: (username: string, password: string, action: 'signin' | 'signup', email?: string) => Promise<void> }) {
  const [mode, setMode] = useState<'signin' | 'create'>('signin'); const [username, setUsername] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [showPassword, setShowPassword] = useState(false); const [authError, setAuthError] = useState(''); const [submitting, setSubmitting] = useState(false); const [recoveryAction, setRecoveryAction] = useState<'username' | 'password' | null>(null); const [recoveryEmail, setRecoveryEmail] = useState(''); const [recoveryMessage, setRecoveryMessage] = useState(''); const [recoverySent, setRecoverySent] = useState(false); const [recovering, setRecovering] = useState(false);
  const usernameValid = /^[a-zA-Z0-9_-]{3,24}$/.test(username); const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()); const passwordValid = password.length >= 8; const valid = usernameValid && passwordValid && (mode === 'signin' || emailValid && password === confirm);
  const submit = async () => { if (!usernameValid) return setAuthError('Use 3–24 letters, numbers, underscores, or hyphens.'); if (mode === 'create' && !emailValid) return setAuthError('Enter a valid email address.'); if (!passwordValid) return setAuthError('Password must contain at least 8 characters.'); if (mode === 'create' && password !== confirm) return setAuthError('Those passwords do not match.'); setAuthError(''); setSubmitting(true); try { await onEnter(username.trim(), password, mode === 'create' ? 'signup' : 'signin', mode === 'create' ? email.trim() : undefined); } catch (error) { setAuthError(error instanceof Error ? error.message : 'Could not sign in.'); } finally { setSubmitting(false); } };
  const recover = async () => { if (!recoveryAction || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recoveryEmail.trim())) { setRecoverySent(false); return setRecoveryMessage('Enter a valid email address.'); } setRecovering(true); setRecoveryMessage(''); setRecoverySent(false); try { await requestAccountRecovery(recoveryEmail.trim(), recoveryAction); setRecoveryMessage('If that email belongs to an account, recovery instructions have been sent.'); setRecoverySent(true); } catch (error) { setRecoveryMessage(error instanceof Error ? error.message : 'Recovery could not be requested.'); } finally { setRecovering(false); } };
  return <LinearGradient colors={[C.ink, '#161B1B', '#251E18']} style={{ flex: 1 }}>
    <SafeAreaView style={s.authWrap}>
      <View style={s.brandMark}><Text style={s.brandRune}>S</Text></View>
      <Text style={s.logo}>SABLE CROWN</Text><Text style={s.authTitle}>{mode === 'signin' ? 'Return to your story.' : 'Claim your name.'}</Text>
      <Text style={s.authCopy}>{mode === 'signin' ? 'Your worlds remember every oath, every wound, and every unfinished thread.' : 'Create one account for your private worlds and persistent campaigns.'}</Text>
      <View style={s.authCard}>
        <View style={s.authTabs}><Pressable onPress={() => { setMode('signin'); setAuthError(''); }} style={[s.authTab, mode === 'signin' && s.authTabActive]}><Text style={[s.authTabText, mode === 'signin' && s.authTabTextActive]}>SIGN IN</Text></Pressable><Pressable onPress={() => { setMode('create'); setAuthError(''); }} style={[s.authTab, mode === 'create' && s.authTabActive]}><Text style={[s.authTabText, mode === 'create' && s.authTabTextActive]}>CREATE ACCOUNT</Text></Pressable></View>
        <View style={s.authLabelRow}><Text style={s.label}>USERNAME</Text>{mode === 'signin' && <Pressable onPress={() => { setRecoveryAction('username'); setRecoveryMessage(''); setRecoverySent(false); }}><Text style={s.authLink}>Forgot username?</Text></Pressable>}</View><View style={s.authInputWrap}><Ionicons name="person-outline" size={18} color={C.muted} /><TextInput value={username} onChangeText={setUsername} placeholder="mara_venn" placeholderTextColor="#666" autoCapitalize="none" autoCorrect={false} style={s.authInput} accessibilityLabel="Username" /></View>
        {mode === 'create' && <><Text style={s.label}>EMAIL</Text><View style={s.authInputWrap}><Ionicons name="mail-outline" size={18} color={C.muted} /><TextInput value={email} onChangeText={setEmail} placeholder="you@example.com" placeholderTextColor="#666" autoCapitalize="none" autoCorrect={false} keyboardType="email-address" autoComplete="email" style={s.authInput} accessibilityLabel="Email address" /></View></>}
        <View style={s.authLabelRow}><Text style={s.label}>PASSWORD</Text>{mode === 'signin' && <Pressable onPress={() => { setRecoveryAction('password'); setRecoveryMessage(''); setRecoverySent(false); }}><Text style={s.authLink}>Forgot password?</Text></Pressable>}</View>
        <View style={s.authInputWrap}><Ionicons name="lock-closed-outline" size={18} color={C.muted} /><TextInput value={password} onChangeText={setPassword} placeholder="At least 8 characters" placeholderTextColor="#666" secureTextEntry={Platform.OS !== 'web' && !showPassword} autoComplete="off" autoCapitalize="none" style={[s.authInput, Platform.OS === 'web' && !showPassword && s.webPasswordMasked]} accessibilityLabel="Password" onSubmitEditing={submit} /><Pressable accessibilityLabel={showPassword ? 'Hide password' : 'Show password'} onPress={() => setShowPassword(v => !v)} style={s.passwordToggle}><Ionicons name={showPassword ? 'eye-off-outline' : 'eye-outline'} size={19} color={C.white} /></Pressable></View>
        {mode === 'create' && <><Text style={s.label}>CONFIRM PASSWORD</Text><View style={[s.authInputWrap, confirm.length > 0 && password !== confirm && s.authInputInvalid]}><Ionicons name="shield-checkmark-outline" size={18} color={confirm.length > 0 && password !== confirm ? '#E28B84' : C.muted} /><TextInput value={confirm} onChangeText={setConfirm} placeholder="Repeat your password" placeholderTextColor="#666" secureTextEntry={Platform.OS !== 'web' && !showPassword} autoComplete="off" autoCapitalize="none" style={[s.authInput, Platform.OS === 'web' && !showPassword && s.webPasswordMasked]} accessibilityLabel="Confirm password" onSubmitEditing={submit} /><Pressable accessibilityLabel={showPassword ? 'Hide password' : 'Show password'} onPress={() => setShowPassword(v => !v)} style={s.passwordToggle}><Ionicons name={showPassword ? 'eye-off-outline' : 'eye-outline'} size={19} color={C.white} /></Pressable></View>{confirm.length > 0 && password !== confirm && <View style={s.fieldError}><Ionicons name="alert-circle-outline" size={14} color="#E28B84" /><Text style={s.fieldErrorText}>Passwords do not match.</Text></View>}</>}
        {authError ? <View style={s.authErrorRow}><Ionicons name="alert-circle-outline" size={16} color="#E28B84" /><Text style={s.error}>{authError}</Text></View> : null}
        <Button label={submitting ? 'Opening the chronicle…' : mode === 'signin' ? 'Enter the realm' : 'Create my account'} icon="arrow-forward" disabled={!valid || submitting} onPress={submit} />
        <View style={s.authDivider}><View style={s.authDividerLine} /><Text style={s.authDividerText}>PRIVATE BY DEFAULT</Text><View style={s.authDividerLine} /></View>
        <Text style={s.fine}>By continuing, you confirm you are 18+ and accept the mature-content boundary. {isSupabaseConfigured ? 'Your account is securely synchronized across devices.' : 'Authentication is device-local until Supabase is configured.'}</Text>
      </View>
    </SafeAreaView><Modal visible={!!recoveryAction} transparent animationType="fade" onRequestClose={() => setRecoveryAction(null)}><View style={s.modalBackdrop}><View style={s.modalCard}>{recoverySent ? <><View style={[s.modalIcon, s.recoverySuccessIcon]}><Ionicons name="checkmark" size={32} color={C.green} /></View><Text style={s.modalTitle}>Check your email</Text><View style={s.recoverySuccess}><Ionicons name="checkmark-circle" size={20} color={C.green} /><Text style={s.recoverySuccessText}>If that email belongs to an account, recovery instructions have been sent.</Text></View><View style={s.modalActions}><Button label="Done" onPress={() => { setRecoveryAction(null); setRecoveryMessage(''); setRecoverySent(false); setRecoveryEmail(''); }} /></View></> : <><View style={s.modalIcon}><Ionicons name={recoveryAction === 'username' ? 'person-outline' : 'key-outline'} size={28} color={C.gold} /></View><Text style={s.modalTitle}>{recoveryAction === 'username' ? 'Recover username' : 'Reset password'}</Text><Text style={s.modalBody}>{recoveryAction === 'username' ? 'Enter the email used to create your account. We will send your username.' : 'Enter the email used to create your account. We will send a secure password-reset link.'}</Text><View style={[s.authInputWrap, { width: '100%' }]}><Ionicons name="mail-outline" size={18} color={C.muted} /><TextInput value={recoveryEmail} onChangeText={setRecoveryEmail} placeholder="you@example.com" placeholderTextColor="#666" keyboardType="email-address" autoCapitalize="none" style={s.authInput} /></View>{recoveryMessage ? <Text style={s.error}>{recoveryMessage}</Text> : null}<View style={s.modalActions}><Button label="Cancel" kind="ghost" onPress={() => { setRecoveryAction(null); setRecoveryMessage(''); setRecoverySent(false); }} /><Button label={recovering ? 'Sending…' : 'Send recovery email'} disabled={recovering} onPress={recover} /></View></>}</View></View></Modal>
  </LinearGradient>;
}

function ResetPassword({ onComplete }: { onComplete: () => void }) { const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [error, setError] = useState(''); const [saving, setSaving] = useState(false); const submit = async () => { if (password.length < 8) return setError('Password must contain at least 8 characters.'); if (password !== confirm) return setError('Those passwords do not match.'); setSaving(true); setError(''); try { await updateRecoveredPassword(password); onComplete(); } catch (value) { setError(value instanceof Error ? value.message : 'Password could not be updated.'); } finally { setSaving(false); } }; return <LinearGradient colors={[C.ink, '#161B1B', '#251E18']} style={{ flex: 1 }}><SafeAreaView style={s.authWrap}><View style={s.brandMark}><Text style={s.brandRune}>S</Text></View><Text style={s.logo}>SABLE CROWN</Text><Text style={s.authTitle}>Choose a new password.</Text><View style={s.authCard}><Text style={s.label}>NEW PASSWORD</Text><TextInput value={password} onChangeText={setPassword} secureTextEntry placeholder="At least 8 characters" placeholderTextColor="#666" style={s.input} /><Text style={s.label}>CONFIRM PASSWORD</Text><TextInput value={confirm} onChangeText={setConfirm} secureTextEntry placeholder="Repeat your password" placeholderTextColor="#666" style={s.input} />{error ? <Text style={s.error}>{error}</Text> : null}<Button label={saving ? 'Saving…' : 'Set new password'} disabled={saving} onPress={submit} /></View></SafeAreaView></LinearGradient>; }

function Nav({ screen, setScreen }: { screen: Screen; setScreen: (v: Screen) => void }) {
  const tabs: [Screen, string, keyof typeof Ionicons.glyphMap][] = [['home', 'Stories', 'book-outline'], ['packs', 'Worlds', 'globe-outline'], ['settings', 'Settings', 'settings-outline']];
  return <View style={s.nav}>{tabs.map(([id, label, icon]) => <Pressable key={id} onPress={() => setScreen(id)} style={s.navItem}><Ionicons name={icon} size={21} color={screen === id ? C.gold : C.muted} /><Text style={[s.navText, screen === id && { color: C.gold }]}>{label}</Text></Pressable>)}</View>;
}

function Home({ data, openCampaign, deleteCampaign, openWorlds, openStore }: { data: AppData; openCampaign: (c: Campaign) => void; deleteCampaign: (c: Campaign) => Promise<void>; openWorlds: () => void; openStore: () => void }) {
  const active = data.campaigns.filter(c => !c.archived);
  const [pendingDelete, setPendingDelete] = useState<Campaign | null>(null); const [deleting, setDeleting] = useState(false);
  const confirmDelete = async () => { if (!pendingDelete || deleting) return; setDeleting(true); try { await deleteCampaign(pendingDelete); setPendingDelete(null); } catch (error) { Alert.alert('Campaign could not be deleted', error instanceof Error ? error.message : 'Please try again.'); } finally { setDeleting(false); } };
  return <><ScrollView contentContainerStyle={[s.page, active.length === 0 && s.emptyStoriesPage]}>
    <View style={s.topline}><View><Text style={s.eyebrow}>WELCOME BACK</Text><Text style={s.h1}>{data.user?.name}</Text></View><View style={s.balanceActions}><View style={s.quota}><Ionicons name="sparkles" size={14} color={C.gold} /><Text style={s.quotaText}>{data.user?.turnsRemaining} turns</Text></View><Pressable accessibilityRole="button" accessibilityLabel="Buy more turns" onPress={openStore} style={({ pressed }) => [s.buyTurns, pressed && { opacity: .7 }]}><Ionicons name="add" size={16} color={C.ink} /><Text style={s.buyTurnsText}>Buy turns</Text></Pressable></View></View>
    {active.length > 0 ? <View style={{ gap: 12 }}><SectionTitle title="Continue your story" />{active.map(c => <Pressable key={c.id} onPress={() => openCampaign(c)} style={s.campaignCard}>
      <LinearGradient colors={['#2B251D', '#15191A']} style={s.campaignGlow}><View style={s.campaignMeta}><Tag>{data.packs.find(pack => pack.id === c.packId && pack.version === c.packVersion)?.metadata.title || 'PRIVATE WORLD'}</Tag><View style={s.campaignCardActions}><Text style={s.muted}>{new Date(c.updatedAt).toLocaleDateString()}</Text><Pressable accessibilityRole="button" accessibilityLabel={`Delete ${c.title}`} hitSlop={8} onPress={event => { event.stopPropagation(); setPendingDelete(c); }} style={s.deleteCampaignButton}><Ionicons name="trash-outline" size={17} color="#E28B84" /></Pressable></View></View><Text style={s.cardTitle}>{c.title}</Text><Text style={s.copy} numberOfLines={2}>{c.state.summary || 'The succession bell has sounded. A dying courier carries a secret.'}</Text><View style={s.row}><Text style={s.goldText}>Continue as {c.character.name}</Text><Ionicons name="arrow-forward" size={18} color={C.gold} /></View></LinearGradient>
    </Pressable>)}</View> : <View style={s.emptyStoriesStage}><View style={s.emptyStories}><View style={s.emptyStoriesIcon}><Ionicons name="book-outline" size={34} color={C.gold} /></View><Text style={s.h2}>No active campaigns</Text><Text style={[s.copy, { textAlign: 'center' }]}>Choose a world to begin a new story. Your campaigns will appear here once they have started.</Text><Button label="Browse worlds" icon="globe-outline" onPress={openWorlds} /></View></View>}
  </ScrollView><ConfirmDialog visible={!!pendingDelete} title="Delete this campaign?" body={pendingDelete ? `“${pendingDelete.title}” and its complete story history, character, world state, memories, and intelligence will be permanently deleted. This cannot be undone.` : ''} confirmLabel={deleting ? 'Deleting…' : 'Delete campaign'} danger onCancel={() => !deleting && setPendingDelete(null)} onConfirm={confirmDelete} /></>;
}

function Store({ balance, onBack, onPurchase }: { balance: number; onBack: () => void; onPurchase: (turns: number) => void }) {
  const packs = [{ turns: 25, price: '£1.99', note: 'A short chapter' }, { turns: 100, price: '£5.99', note: 'Most popular', featured: true }, { turns: 300, price: '£14.99', note: 'Best value' }];
  const [selected, setSelected] = useState<(typeof packs)[number] | null>(null);
  return <><ScrollView contentContainerStyle={s.page}><Pressable onPress={onBack} style={s.back}><Ionicons name="arrow-back" size={18} color={C.muted} /><Text style={s.muted}>Stories</Text></Pressable><View style={s.storeHeading}><View><Text style={s.eyebrow}>STORY CREDIT</Text><Text style={s.h1}>Buy turns</Text></View><View style={s.quota}><Ionicons name="sparkles" size={14} color={C.gold} /><Text style={s.quotaText}>{balance} available</Text></View></View><Text style={s.copy}>A turn is charged only after the game successfully advances your story. Failed, blocked, or interrupted responses cost nothing.</Text><View style={s.storeGrid}>{packs.map(pack => <Pressable key={pack.turns} onPress={() => setSelected(pack)} style={({ pressed }) => [s.turnPack, pack.featured && s.turnPackFeatured, pressed && { opacity: .75 }]}>{pack.featured && <Text style={s.packRibbon}>MOST POPULAR</Text>}<Ionicons name="sparkles" size={24} color={C.gold} /><Text style={s.turnCount}>{pack.turns}</Text><Text style={s.turnLabel}>STORY TURNS</Text><Text style={s.packPrice}>{pack.price}</Text><Text style={s.muted}>{pack.note}</Text><View style={[s.packBuy, pack.featured && { backgroundColor: C.gold }]}><Text style={[s.packBuyText, pack.featured && { color: C.ink }]}>Choose pack</Text></View></Pressable>)}</View><View style={s.notice}><Ionicons name="information-circle-outline" size={22} color={C.gold} /><View style={{ flex: 1 }}><Text style={s.noticeTitle}>Prototype checkout</Text><Text style={s.copy}>Selecting a pack currently adds demonstration turns without charging you. Production purchases will use the appropriate web or mobile store checkout.</Text></View></View></ScrollView><ConfirmDialog visible={!!selected} title="Confirm turn pack" body={selected ? `${selected.turns} story turns · ${selected.price}\n\nThis prototype will not charge you.` : ''} confirmLabel="Confirm purchase" onCancel={() => setSelected(null)} onConfirm={() => { if (selected) onPurchase(selected.turns); setSelected(null); }} /></>;
}

function OptionPicker({ label, entries, value, onChange }: { label: string; entries: NamedEntry[]; value?: NamedEntry; onChange: (v: NamedEntry) => void }) {
  return <View style={{ gap: 8 }}><Text style={s.label}>{label}</Text><View style={s.optionGrid}>{entries.map(e => <Pressable key={e.id} onPress={() => onChange(e)} style={[s.option, value?.id === e.id && s.optionActive]}><Text style={[s.optionName, value?.id === e.id && { color: C.gold }]}>{e.name}</Text><Text style={s.optionCopy}>{e.description}</Text></Pressable>)}</View></View>;
}

function CharacterCreate({ pack, onBack, onCreate }: { pack: WorldPack; onBack: () => void; onCreate: (c: Character, campaignName: string) => void }) {
  const o = pack.characterOptions; const preset = pack.openingScenario?.playerPreset; const find = (entries: NamedEntry[], id?: string) => entries.find(entry => entry.id === id);
  const [campaignName, setCampaignName] = useState(''); const [name, setName] = useState(preset?.name || ''); const [pronouns, setPronouns] = useState(preset?.pronouns || 'he/him');
  const [background, setBackground] = useState<NamedEntry | undefined>(() => find(o.backgrounds, preset?.backgroundId)); const [strength, setStrength] = useState<NamedEntry | undefined>(() => find(o.strengths, preset?.strengthId)); const [weakness, setWeakness] = useState<NamedEntry | undefined>(() => find(o.weaknesses, preset?.weaknessId)); const [motivation, setMotivation] = useState<NamedEntry | undefined>(() => find(o.motivationsByBackground?.[preset?.backgroundId || ''] || o.motivations, preset?.motivationId)); const [motivationMode, setMotivationMode] = useState<'guided' | 'custom' | 'discover'>('guided'); const [customMotivation, setCustomMotivation] = useState('');
  const motivations = background ? o.motivationsByBackground?.[background.id] || o.motivations : [];
  const selectedMotivation = motivationMode === 'custom' ? { id: 'custom-motivation', name: customMotivation.trim(), description: 'A personal ambition written by the player.' } : motivationMode === 'discover' ? { id: 'story-decides', name: 'Let the Story Decide', description: 'Begin without a declared ambition and discover it through play.' } : motivation;
  const valid = campaignName.trim().length >= 3 && name.trim() && background && strength && weakness && selectedMotivation && (motivationMode !== 'custom' || customMotivation.trim().length >= 5);
  return <ScrollView contentContainerStyle={s.page}><Pressable onPress={onBack} style={s.back}><Ionicons name="arrow-back" size={18} color={C.muted} /><Text style={s.muted}>Worlds</Text></Pressable><SectionTitle eyebrow={pack.metadata.title.toUpperCase()} title="Who enters the story?" copy="Your history opens doors. Your flaws decide which ones close behind you." />
    <View style={s.formCard}><Text style={s.label}>CAMPAIGN NAME</Text><TextInput value={campaignName} onChangeText={setCampaignName} placeholder="For example: The Just King" placeholderTextColor="#687074" maxLength={80} style={s.input} /><Text style={s.fineLeft}>Give this story a distinct name so you can tell multiple campaigns in the same world apart.</Text><Text style={s.label}>CHARACTER NAME</Text><TextInput value={name} onChangeText={setName} placeholder="Name your character" placeholderTextColor="#687074" maxLength={80} style={s.input} /><Text style={s.label}>PRONOUNS</Text><View style={s.pillRow}>{['he/him', 'she/her'].map(p => <Pressable key={p} onPress={() => setPronouns(p)} style={[s.pill, pronouns === p && s.pillActive]}><Text style={[s.pillText, pronouns === p && { color: C.ink }]}>{p}</Text></Pressable>)}</View></View>
    <OptionPicker label="BACKGROUND" entries={o.backgrounds} value={background} onChange={value => { setBackground(value); setMotivation(undefined); setMotivationMode('guided'); }} /><OptionPicker label="STRENGTH" entries={o.strengths} value={strength} onChange={setStrength} /><OptionPicker label="WEAKNESS" entries={o.weaknesses} value={weakness} onChange={setWeakness} />
    {background && <View style={{ gap: 10 }}><Text style={s.label}>MOTIVATION</Text><Text style={s.copy}>Choose a direction, write your own ambition, or discover what matters through play.</Text><View style={s.pillRow}>{([['guided','Choose'],['custom','Write my own'],['discover','Let the story decide']] as const).map(([id,label]) => <Pressable key={id} onPress={() => { setMotivationMode(id); if (id !== 'guided') setMotivation(undefined); }} style={[s.pill, motivationMode === id && s.pillActive]}><Text style={[s.pillText, motivationMode === id && { color: C.ink }]}>{label}</Text></Pressable>)}</View>{motivationMode === 'guided' && <OptionPicker label={`${background.name.toUpperCase()} AMBITIONS`} entries={motivations} value={motivation} onChange={setMotivation} />}{motivationMode === 'custom' && <TextInput value={customMotivation} onChangeText={setCustomMotivation} placeholder="What does your character want above all else?" placeholderTextColor="#687074" maxLength={160} multiline style={s.input} />}{motivationMode === 'discover' && <View style={s.notice}><Ionicons name="compass-outline" size={22} color={C.gold} /><View style={{ flex: 1 }}><Text style={s.noticeTitle}>An unwritten ambition</Text><Text style={s.copy}>The opening chapters will present possibilities, but only your choices will define what this character truly wants.</Text></View></View>}</View>}
    <Button label="Step into the story" icon="arrow-forward" disabled={!valid} onPress={() => valid && onCreate({ name: name.trim(), pronouns, background, strength, weakness, motivation: selectedMotivation }, campaignName.trim())} />
  </ScrollView>;
}

function Play({ campaign, pack, updateCampaign, onExit, onOpenIntel }: { campaign: Campaign; pack: WorldPack; updateCampaign: (c: Campaign, charge?: number) => void; onExit: () => void; onOpenIntel: () => void }) {
  const [text, setText] = useState(''); const [sending, setSending] = useState(false); const [error, setError] = useState(''); const [scrollMetrics, setScrollMetrics] = useState({ content: 1, viewport: 1, offset: 0 }); const [inputMetrics, setInputMetrics] = useState({ content: 1, viewport: 1, offset: 0 }); const scroll = useRef<ScrollView>(null); const { width } = useWindowDimensions(); const wide = width > 860;
  const readScrollOffset = (event: any) => event?.nativeEvent?.contentOffset?.y ?? event?.currentTarget?.scrollTop ?? event?.target?.scrollTop ?? 0;
  const trackHeight = Math.max(1, scrollMetrics.viewport - 12); const thumbHeight = Math.max(42, Math.min(trackHeight, trackHeight * scrollMetrics.viewport / scrollMetrics.content)); const maxOffset = Math.max(1, scrollMetrics.content - scrollMetrics.viewport); const thumbTop = 6 + Math.min(1, scrollMetrics.offset / maxOffset) * Math.max(0, trackHeight - thumbHeight);
  const inputTrackHeight = Math.max(1, inputMetrics.viewport - 8); const inputThumbHeight = Math.max(20, Math.min(inputTrackHeight, inputTrackHeight * inputMetrics.viewport / inputMetrics.content)); const inputMaxOffset = Math.max(1, inputMetrics.content - inputMetrics.viewport); const inputThumbTop = 4 + Math.min(1, inputMetrics.offset / inputMaxOffset) * Math.max(0, inputTrackHeight - inputThumbHeight);
  const send = async (value = text) => { if (!value.trim() || sending) return; setSending(true); setError(''); const key = uuid(); try { if (isSupabaseConfigured) { const result = await submitRemoteTurn(campaign.id, value.trim(), key); updateCampaign({ ...campaign, state: applyStateChanges(campaign.state, result.stateChanges), turns: result.chapterTransition ? [result.turn] : [...campaign.turns, result.turn], currentChapter: result.chapterNumber || campaign.currentChapter || 1, chapterTitle: result.chapterTitle || campaign.chapterTitle, chapterSummary: result.chapterSummary || campaign.chapterSummary, updatedAt: new Date().toISOString() }, result.usage); } else { const result = await submitLocalTurn(campaign, pack, value.trim(), key); updateCampaign({ ...campaign, state: result.nextState, turns: [...campaign.turns, result.turn], updatedAt: new Date().toISOString() }, result.usage); } setText(''); setTimeout(() => scroll.current?.scrollToEnd({ animated: true }), 80); } catch (e) { setError(e instanceof Error ? e.message : 'The story could not advance. Your turn was not saved.'); } finally { setSending(false); } };
  const currentChapter = campaign.currentChapter || 1; const chapterHeading = campaign.chapterTitle || (currentChapter === 1 ? pack.openingScenario?.chapterLabel || 'CHAPTER I · THE EMPTY THRONE' : `CHAPTER ${currentChapter}`); const chapterOpening = currentChapter === 1 ? pack.openingScenario?.narration.replaceAll('{name}', campaign.character.name) || openingNarration(campaign.character.name, campaign.character.background.id) : campaign.chapterSummary || campaign.state.summary;
  const story = <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={s.playMain}><View style={s.playHead}><Pressable accessibilityRole="button" accessibilityLabel="Leave story and return to stories" onPress={onExit} style={({ pressed }) => [s.exitStory, pressed && { opacity: .7 }]}><Ionicons name="arrow-back" size={18} color={C.gold} /><Text style={s.exitStoryText}>Back to stories</Text></Pressable><View style={s.playHeading}><Text numberOfLines={1} style={s.playTitle}>{campaign.title}</Text><Text style={s.playSub}>{pack.locations.find(l => l.id === campaign.state.locationId)?.name}</Text></View><Pressable accessibilityLabel="Open world intelligence" onPress={onOpenIntel} style={s.intelHeaderButton}><Ionicons name="library-outline" size={18} color={C.gold} /><Text style={s.intelHeaderText}>World intel</Text></Pressable></View>
    <View style={s.storyScrollWrap}><ScrollView style={s.storyScroll} showsVerticalScrollIndicator={false} ref={scroll} scrollEventThrottle={16} onLayout={e => setScrollMetrics(m => ({ ...m, viewport: e.nativeEvent.layout.height }))} onScroll={e => setScrollMetrics(m => ({ ...m, offset: readScrollOffset(e) }))} contentContainerStyle={s.story} onContentSizeChange={(_, height) => { setScrollMetrics(m => ({ ...m, content: height })); scroll.current?.scrollToEnd({ animated: false }); }}><Text style={s.chapter}>{chapterHeading}</Text>{campaign.state.campaignDate && <Text style={s.chapter}>{`${campaign.state.campaignDate.year} · DAY ${campaign.state.campaignDate.day} · ${campaign.state.campaignDate.segment.toUpperCase()}`}</Text>}<Text style={s.narration}>{chapterOpening}</Text>{campaign.turns.map(t => <View key={t.id} style={{ gap: 16 }}><View style={s.playerTurn}><Text style={s.playerText}>{t.playerText}</Text><Text style={s.intentLine}>{[...t.intent.speech.map(x => `Said: “${x}”`), ...t.intent.actions.map(x => `Action: ${x}`)].join('  ·  ')}</Text></View>{t.dateLabel && <Text style={s.chapter}>{t.dateLabel}</Text>}<Text style={s.narration}>{t.narration}</Text><View style={s.suggestions}>{t.suggestions.map(x => <Pressable key={x} onPress={() => send(x)} style={s.suggestion}><Text style={s.suggestionText}>{x}</Text></Pressable>)}</View></View>)}{sending && <View style={s.thinking}><ActivityIndicator color={C.gold} /><Text style={s.muted}>The world is answering…</Text></View>}</ScrollView>{scrollMetrics.content > scrollMetrics.viewport && <View pointerEvents="none" style={s.customScrollTrack}><View style={[s.customScrollThumb, { height: thumbHeight, top: thumbTop }]} /></View>}</View>
    {campaign.state.condition === 'dead' ? <View style={s.campaignEnded}><Ionicons name="skull-outline" size={22} color="#E28B84" /><View style={{ flex: 1 }}><Text style={s.noticeTitle}>This character has died</Text><Text style={s.copy}>Their story is over. The campaign remains available as a permanent chronicle.</Text></View></View> : <View style={s.composer}><View style={s.composeRow}><View style={s.composeInputWrap}><TextInput testID="composer-input" multiline value={text} onChangeText={setText} placeholder="What do you say or do?" placeholderTextColor="#727778" style={s.composeInput} onLayout={e => setInputMetrics(m => ({ ...m, viewport: e.nativeEvent.layout.height }))} onContentSizeChange={e => setInputMetrics(m => ({ ...m, content: e.nativeEvent.contentSize.height }))} onScroll={e => setInputMetrics(m => ({ ...m, offset: readScrollOffset(e) }))} onSubmitEditing={() => send()} /><View pointerEvents="none" style={s.inputScrollMask} />{inputMetrics.content > inputMetrics.viewport + 2 && <View pointerEvents="none" style={s.inputScrollTrack}><View style={[s.inputScrollThumb, { height: inputThumbHeight, top: inputThumbTop }]} /></View>}</View><Pressable disabled={!text.trim() || sending} onPress={() => send()} style={[s.send, (!text.trim() || sending) && { opacity: .4 }]}><Ionicons name="arrow-up" color={C.ink} size={22} /></Pressable></View><Text style={s.fine}>Speak, act, or combine both. The game interprets your intent.</Text></View>}<StoryErrorDialog error={error} campaignId={campaign.id} onClose={() => setError('')} /></KeyboardAvoidingView>;
  const side = <View style={s.side}><Text style={s.label}>YOUR CHARACTER</Text><Text style={s.sideName}>{campaign.character.name}</Text><Text style={s.copy}>{campaign.character.background.name}</Text><View style={s.meterRow}><Text style={s.muted}>Health</Text><Text style={s.goldText}>{campaign.state.health}</Text></View><View style={s.meter}><View style={[s.meterFill, { width: `${campaign.state.health}%` }]} /></View><View style={s.meterRow}><Text style={s.muted}>Resolve</Text><Text style={s.goldText}>{campaign.state.resolve}</Text></View><View style={s.meter}><View style={[s.meterFill, { width: `${campaign.state.resolve}%` }]} /></View><Text style={[s.label, { marginTop: 18 }]}>INVENTORY</Text>{campaign.state.inventory.map(x => <View key={x} style={s.inventory}><Ionicons name="diamond-outline" size={15} color={C.gold} /><Text style={s.copy}>{x}</Text></View>)}<Text style={[s.label, { marginTop: 18 }]}>KNOWN THREADS</Text>{campaign.state.unresolvedThreads.map(x => <Text key={x} style={s.thread}>• {x}</Text>)}</View>;
  return <SafeAreaView style={s.playWrap}>{wide && side}{story}</SafeAreaView>;
}

function LegacyWorldIntel({ campaign, pack, onBack }: { campaign: Campaign; pack: WorldPack; onBack: () => void }) {
  const [tab, setTab] = useState<'characters' | 'factions' | 'locations' | 'resources'>('characters');
  const [remoteDb, setRemoteDb] = useState<any>(null); const [intelError, setIntelError] = useState('');
  useEffect(() => { if (!isSupabaseConfigured) return; getWorldDatabase(campaign.id).then(setRemoteDb).catch(error => setIntelError(error instanceof Error ? error.message : 'World intelligence could not be loaded.')); }, [campaign.id]);
  const currentLocation = pack.locations.find(l => l.id === campaign.state.locationId)?.name || 'Unknown';
  const confidence = (level: string) => <View style={[s.confidence, level === 'CONFIRMED' ? s.confidenceHigh : level === 'MEDIUM' ? s.confidenceMedium : s.confidenceLow]}><Text style={s.confidenceText}>{level}</Text></View>;
  const locationName = (id: string | null) => remoteDb?.locations.find((location: any) => location.id === id)?.name || 'Unknown';
  const entityFor = (id: string) => remoteDb?.entities.find((entity: any) => entity.id === id);
  const characterRows = remoteDb ? [{ name: campaign.character.name, role: campaign.character.background.name, location: locationName(remoteDb.characters.find((row: any) => row.name === campaign.character.name)?.status?.locationId) || currentLocation, seen: 'Current', level: 'CONFIRMED', status: `${campaign.state.health} health · Active` }, ...remoteDb.knowledge.map((known: any) => { const entity = entityFor(known.entity_id); const character = remoteDb.characters.find((row: any) => row.entity_id === known.entity_id); return { name: entity?.canonical_name || character?.name || 'Unknown figure', role: entity?.public_description || 'Identity uncertain', location: locationName(known.believed_location_id), seen: known.last_confirmed_at ? new Date(known.last_confirmed_at).toLocaleString() : 'Unknown', level: String(known.confidence || 'unknown').toUpperCase(), status: known.known_status?.label || 'Status uncertain' }; })] : [{ name: campaign.character.name, role: campaign.character.background.name, location: currentLocation, seen: 'Current', level: 'CONFIRMED', status: 'Healthy · Active' }, ...pack.npcs.map((npc, index) => ({ name: npc.name, role: npc.description, location: index === 0 ? 'Northern gallery, Gloamspire' : index === 1 ? 'Believed within Gloamspire' : 'Reed Market district', seen: index === 0 ? 'Moments ago' : index === 1 ? 'Today' : '6 days ago', level: index === 0 ? 'HIGH' : index === 1 ? 'MEDIUM' : 'LOW', status: index === 2 ? 'Unconfirmed' : 'Active' }))];
  const knownLocations = remoteDb ? remoteDb.locations : pack.locations.map((location: any, index: number) => ({ ...location, public_description: location.description, location_type: index === 0 ? 'settlement' : 'landmark' }));
  return <SafeAreaView style={s.root}><ScrollView contentContainerStyle={s.intelPage}><View style={s.intelTop}><Pressable onPress={onBack} style={s.back}><Ionicons name="arrow-back" size={18} color={C.gold} /><Text style={s.goldText}>Return to story</Text></Pressable><View style={s.intelSeal}><Ionicons name="library-outline" size={25} color={C.gold} /></View></View><SectionTitle eyebrow="CAMPAIGN INTELLIGENCE" title="World ledger" copy="What you know—not necessarily what is true. Reports decay, sources conflict, and locations may be deliberately imprecise." /><View style={s.intelTabs}>{(['characters','factions','locations','resources'] as const).map(id => <Pressable key={id} onPress={() => setTab(id)} style={[s.intelTab, tab === id && s.intelTabActive]}><Text style={[s.intelTabText, tab === id && { color: C.gold }]}>{id.toUpperCase()}</Text></Pressable>)}</View>
    {tab === 'characters' && <View style={s.intelTable}><View style={s.intelTableHead}><Text style={[s.intelColHead,{flex:1.2}]}>PERSON</Text><Text style={[s.intelColHead,{flex:1.4}]}>BELIEVED LOCATION</Text><Text style={[s.intelColHead,{flex:.8}]}>LAST SEEN</Text><Text style={[s.intelColHead,{width:90}]}>CONFIDENCE</Text></View>{characterRows.map(row => <View key={row.name} style={s.intelRow}><View style={{flex:1.2}}><Text style={s.intelName}>{row.name}</Text><Text numberOfLines={2} style={s.intelDetail}>{row.role}</Text></View><View style={{flex:1.4}}><Text style={s.intelValue}>{row.location}</Text><Text style={s.intelDetail}>{row.status}</Text></View><Text style={[s.intelValue,{flex:.8}]}>{row.seen}</Text><View style={{width:90}}>{confidence(row.level)}</View></View>)}</View>}
    {tab === 'factions' && <View style={s.intelCards}>{pack.factions.map((f,index) => <View key={f.id} style={s.intelCard}><View style={s.row}><Text style={s.intelName}>{f.name}</Text>{confidence(index === 0 ? 'HIGH' : 'MEDIUM')}</View><Text style={s.copy}>{f.description}</Text><Text style={s.intelDetail}>Known resources: {index === 0 ? 'Mountain levies · strained treasury' : 'River barges · grain stores · unknown reserves'}</Text><Text style={s.intelDetail}>Disposition: {index === 0 ? 'Watchful' : 'Uncertain'}</Text></View>)}</View>}
    {intelError ? <Text style={s.error}>{intelError}</Text> : null}
    {tab === 'locations' && <View style={s.intelCards}>{knownLocations.map((l: any,index: number) => <View key={l.id} style={s.intelCard}><View style={s.row}><Text style={s.intelName}>{l.name}</Text>{confidence(index === 0 ? 'CONFIRMED' : 'MEDIUM')}</View><Text style={s.copy}>{l.public_description || l.description}</Text><Text style={s.intelDetail}>{index === 0 ? 'Starting area · exact details known' : `${l.location_type || 'Regional'} knowledge · interior details incomplete`}</Text></View>)}</View>}
    {tab === 'resources' && <View style={s.intelCards}><View style={s.intelCard}><Text style={s.intelName}>Personal resources</Text>{campaign.state.inventory.map(item => <View key={item} style={s.resourceLine}><Ionicons name="diamond-outline" size={15} color={C.gold} /><Text style={s.intelValue}>{item}</Text><Text style={s.resourceKnown}>KNOWN</Text></View>)}</View><View style={s.intelCard}><Text style={s.intelName}>Strategic estimates</Text><View style={s.resourceLine}><Text style={s.intelValue}>Valehart field strength</Text><Text style={s.intelEstimate}>3,000–5,000</Text></View><View style={s.resourceLine}><Text style={s.intelValue}>Capital grain reserve</Text><Text style={s.intelEstimate}>18–30 days</Text></View><Text style={s.intelDetail}>Estimates reflect reports available to your character and may be wrong.</Text></View></View>}
  </ScrollView></SafeAreaView>;
}

function WorldIntel({ campaign, pack, onBack }: { campaign: Campaign; pack: WorldPack; onBack: () => void }) {
  const [tab, setTab] = useState<'characters' | 'factions' | 'locations' | 'resources' | 'chapters'>('characters');
  const [remoteDb, setRemoteDb] = useState<any>(null); const [intelError, setIntelError] = useState(''); const [search, setSearch] = useState(''); const [page, setPage] = useState(1); const [selectedCharacter, setSelectedCharacter] = useState<any>(null); const [selectedChapter, setSelectedChapter] = useState<any>(null); const pageSize = 8;
  useEffect(() => { if (!isSupabaseConfigured) return; getWorldDatabase(campaign.id).then(setRemoteDb).catch(error => setIntelError(error instanceof Error ? error.message : 'World intelligence could not be loaded.')); }, [campaign.id]);
  useEffect(() => setPage(1), [tab, search]);
  const currentLocation = (remoteDb?.locations || pack.locations).find((location: any) => location.id === campaign.state.locationId)?.name || 'Unknown';
  const worldNow = campaign.state.campaignDate ? `${campaign.state.campaignDate.year} · Day ${campaign.state.campaignDate.day} · ${campaign.state.campaignDate.segment}` : 'Current';
  const locationName = (id: string | null) => remoteDb?.locations.find((location: any) => location.id === id)?.name || 'Unknown';
  const relationshipScore = (name: string) => Number(remoteDb?.relationships?.find((item: any) => item.entity_name.toLowerCase() === name.toLowerCase())?.score ?? campaign.state.relationships[name] ?? 0);
  const relationship = (name: string) => { const value = relationshipScore(name); return value >= 75 ? 'Great' : value >= 25 ? 'Good' : value <= -75 ? 'Awful' : value <= -25 ? 'Bad' : 'Average'; };
  const relationshipBadge = (label: string) => <View style={[s.confidence, label === 'Great' || label === 'Good' ? s.confidenceHigh : label === 'Awful' || label === 'Bad' ? s.confidenceLow : s.confidenceMedium]}><Text style={s.confidenceText}>{label.toUpperCase()}</Text></View>;
  const confidence = (level: string) => <View style={[s.confidence, level === 'CONFIRMED' || level === 'HIGH' ? s.confidenceHigh : level === 'MEDIUM' ? s.confidenceMedium : s.confidenceLow]}><Text style={s.confidenceText}>{level}</Text></View>;
  const entityFor = (id: string) => remoteDb?.entities.find((entity: any) => entity.id === id);
  const characterRows = remoteDb ? [{ name: campaign.character.name, role: campaign.character.background.name, location: currentLocation, seen: worldNow, level: 'CONFIRMED', status: `${campaign.state.health} health · ${campaign.state.condition || 'alive'}`, relationship: 'Great', relationshipScore: 100, entityId: remoteDb.characters.find((row: any) => row.name === campaign.character.name)?.entity_id, isPlayer: true }, ...remoteDb.knowledge.map((known: any) => { const entity = entityFor(known.entity_id); const character = remoteDb.characters.find((row: any) => row.entity_id === known.entity_id); const name = entity?.canonical_name || character?.name || 'Unknown figure'; return { name, role: entity?.public_description || 'Identity uncertain', location: known.believed_location_id ? locationName(known.believed_location_id) : 'Unknown', seen: known.known_status?.lastSeenWorldDate || 'Unknown', level: String(known.confidence || 'unknown').toUpperCase(), status: known.known_status?.label || 'Status uncertain', relationship: relationship(name), relationshipScore: relationshipScore(name), entityId: known.entity_id, source: known.source_summary }; })] : [{ name: campaign.character.name, role: campaign.character.background.name, location: currentLocation, seen: worldNow, level: 'CONFIRMED', status: `${campaign.state.health} health · ${campaign.state.condition || 'alive'}`, relationship: 'Great', relationshipScore: 100, isPlayer: true }, ...pack.npcs.map(npc => ({ name: npc.name, role: npc.description, location: 'Unknown', seen: 'Unknown', level: 'UNKNOWN', status: 'Status uncertain', relationship: relationship(npc.name), relationshipScore: relationshipScore(npc.name), entityId: npc.id }))];
  const locations = remoteDb ? remoteDb.locations : pack.locations.map(location => ({ ...location, public_description: location.description, location_type: 'unknown' }));
  const query = search.trim().toLowerCase(); const matches = (values: unknown[]) => !query || values.some(value => String(value || '').toLowerCase().includes(query));
  const filteredCharacters = characterRows.filter((row: any) => matches([row.name, row.role, row.location, row.status, row.relationship]));
  const filteredFactions = pack.factions.filter(faction => matches([faction.name, faction.description]));
  const filteredLocations = locations.filter((location: any) => matches([location.name, location.public_description, location.description, location.location_type]));
  const filteredChapters = (remoteDb?.chapterSummaries || []).filter((chapter: any) => matches([chapter.title, chapter.summary, chapter.transition_reason, chapter.chapter_number]));
  const resourceItems = remoteDb?.resourceAccounts?.length ? remoteDb.resourceAccounts.filter((account: any) => matches([account.name, account.controller_name, account.account_type, account.status])) : campaign.state.inventory.filter(item => matches([item]));
  const activeItems: any[] = tab === 'characters' ? filteredCharacters : tab === 'factions' ? filteredFactions : tab === 'locations' ? filteredLocations : tab === 'chapters' ? filteredChapters : resourceItems;
  const pageCount = Math.max(1, Math.ceil(activeItems.length / pageSize)); const safePage = Math.min(page, pageCount); const visible = activeItems.slice((safePage - 1) * pageSize, safePage * pageSize);
  const pager = activeItems.length > pageSize && <View style={s.pagination}><Pressable disabled={safePage === 1} onPress={() => setPage(value => Math.max(1, value - 1))} style={[s.pageButton, safePage === 1 && { opacity: .35 }]}><Ionicons name="chevron-back" size={16} color={C.gold} /><Text style={s.goldText}>Previous</Text></Pressable><Text style={s.muted}>{`Page ${safePage} of ${pageCount} · ${activeItems.length} records`}</Text><Pressable disabled={safePage === pageCount} onPress={() => setPage(value => Math.min(pageCount, value + 1))} style={[s.pageButton, safePage === pageCount && { opacity: .35 }]}><Text style={s.goldText}>Next</Text><Ionicons name="chevron-forward" size={16} color={C.gold} /></Pressable></View>;
  const selectedHistory = selectedCharacter ? (remoteDb?.relationshipHistory || []).filter((entry: any) => entry.entity_name.toLowerCase() === selectedCharacter.name.toLowerCase()) : [];
  const money = (value: unknown, currency = 'gold') => `${Number(value || 0).toLocaleString(undefined, { maximumFractionDigits: 2 })} ${currency}`;
  if (selectedChapter) return <SafeAreaView style={s.root}><ScrollView contentContainerStyle={s.intelPage}><View style={s.intelTop}><Pressable onPress={() => setSelectedChapter(null)} style={s.back}><Ionicons name="arrow-back" size={18} color={C.gold} /><Text style={s.goldText}>Chapter list</Text></Pressable><View style={s.intelSeal}><Ionicons name="book-outline" size={25} color={C.gold} /></View></View><SectionTitle eyebrow={`CHAPTER ${selectedChapter.chapter_number}`} title={selectedChapter.title || `Chapter ${selectedChapter.chapter_number}`} copy={selectedChapter.transition_reason || 'A completed chapter in this campaign.'} /><View style={s.chapterSummaryCard}><Text style={s.label}>CHAPTER SUMMARY</Text><Text style={s.chapterSummaryText}>{selectedChapter.summary}</Text></View><View style={s.dossierGrid}><View style={s.dossierFact}><Text style={s.label}>STORY PROGRESS</Text><Text style={s.intelName}>Through turn {selectedChapter.through_turn}</Text></View><View style={s.dossierFact}><Text style={s.label}>COMPLETED</Text><Text style={s.intelValue}>{new Date(selectedChapter.created_at).toLocaleString()}</Text></View></View><SectionTitle eyebrow="CARRIED FORWARD" title="Unresolved threads" copy="These questions remained open when the chapter ended." />{Array.isArray(selectedChapter.unresolved_threads) && selectedChapter.unresolved_threads.length ? <View style={s.intelCards}>{selectedChapter.unresolved_threads.map((thread: string) => <View key={thread} style={s.resourceLine}><Ionicons name="help-circle-outline" size={17} color={C.gold} /><Text style={s.intelValue}>{thread}</Text></View>)}</View> : <View style={s.notice}><Ionicons name="checkmark-circle-outline" size={22} color={C.green} /><Text style={s.copy}>No unresolved threads were carried forward.</Text></View>}</ScrollView></SafeAreaView>;
  if (selectedCharacter) return <SafeAreaView style={s.root}><ScrollView contentContainerStyle={s.intelPage}><View style={s.intelTop}><Pressable onPress={() => setSelectedCharacter(null)} style={s.back}><Ionicons name="arrow-back" size={18} color={C.gold} /><Text style={s.goldText}>Character summary</Text></Pressable><View style={s.intelSeal}><Ionicons name="person-outline" size={25} color={C.gold} /></View></View><SectionTitle eyebrow="CHARACTER DOSSIER" title={selectedCharacter.name} copy={selectedCharacter.role} /><View style={s.dossierGrid}><View style={s.dossierFact}><Text style={s.label}>RELATIONSHIP</Text>{relationshipBadge(selectedCharacter.relationship)}<Text style={s.intelDetail}>{selectedCharacter.isPlayer ? 'Your character' : `${selectedCharacter.relationshipScore > 0 ? '+' : ''}${selectedCharacter.relationshipScore} standing`}</Text></View><View style={s.dossierFact}><Text style={s.label}>BELIEVED LOCATION</Text><Text style={s.intelName}>{selectedCharacter.location}</Text><Text style={s.intelDetail}>{selectedCharacter.source || 'Based on current campaign knowledge'}</Text></View><View style={s.dossierFact}><Text style={s.label}>LAST SEEN</Text><Text style={s.intelValue}>{selectedCharacter.seen}</Text></View><View style={s.dossierFact}><Text style={s.label}>STATUS</Text><Text style={s.intelValue}>{selectedCharacter.status}</Text>{confidence(selectedCharacter.level)}</View></View><SectionTitle eyebrow="RELATIONSHIP HISTORY" title="Why your standing changed" copy="Only events that actually affected this relationship are recorded." />{selectedCharacter.isPlayer ? <View style={s.notice}><Ionicons name="person-outline" size={22} color={C.gold} /><Text style={s.copy}>This is your player character, so no relationship score is calculated.</Text></View> : selectedHistory.length ? <View style={s.intelCards}>{selectedHistory.map((entry: any) => <View key={entry.id} style={s.relationshipEvent}><View style={[s.relationshipDelta, entry.change > 0 ? s.relationshipPositive : s.relationshipNegative]}><Text style={s.relationshipDeltaText}>{entry.change > 0 ? '+' : ''}{entry.change}</Text></View><View style={{ flex: 1 }}><Text style={s.intelValue}>{entry.reason}</Text><Text style={s.intelDetail}>{new Date(entry.created_at).toLocaleString()}</Text></View></View>)}</View> : <View style={s.notice}><Ionicons name="remove-circle-outline" size={22} color={C.gold} /><Text style={s.copy}>No relationship-changing events have occurred yet. The current standing is neutral.</Text></View>}</ScrollView></SafeAreaView>;
  return <SafeAreaView style={s.root}><ScrollView contentContainerStyle={s.intelPage}><View style={s.intelTop}><Pressable onPress={onBack} style={s.back}><Ionicons name="arrow-back" size={18} color={C.gold} /><Text style={s.goldText}>Return to story</Text></Pressable><View style={s.intelSeal}><Ionicons name="library-outline" size={25} color={C.gold} /></View></View><SectionTitle eyebrow="CAMPAIGN INTELLIGENCE" title="World ledger" copy="What your character currently believes—not necessarily what is objectively true." /><View style={s.intelTabs}>{(['characters','factions','locations','resources','chapters'] as const).map(id => <Pressable key={id} onPress={() => { setTab(id); setSelectedCharacter(null); setSelectedChapter(null); }} style={[s.intelTab, tab === id && s.intelTabActive]}><Text style={[s.intelTabText, tab === id && { color: C.gold }]}>{id.toUpperCase()}</Text></Pressable>)}</View><View style={s.authInputWrap}><Ionicons name="search-outline" size={18} color={C.muted} /><TextInput value={search} onChangeText={setSearch} placeholder={`Search ${tab}…`} placeholderTextColor="#687074" style={s.authInput} /></View>
    {intelError ? <Text style={s.error}>{intelError}</Text> : null}
    {!visible.length && <View style={s.notice}><Ionicons name={tab === 'chapters' ? 'book-outline' : 'help-circle-outline'} size={22} color={C.gold} /><Text style={s.copy}>{tab === 'chapters' && !search.trim() ? 'No chapters have been completed yet. The current chapter will appear here after a meaningful narrative transition.' : 'No known information matches this search.'}</Text></View>}
    {tab === 'characters' && !!visible.length && <View style={s.intelTable}><View style={s.intelTableHead}><Text style={[s.intelColHead,{flex:1.3}]}>PERSON</Text><Text style={[s.intelColHead,{flex:1.1}]}>BELIEVED LOCATION</Text><Text style={[s.intelColHead,{flex:1}]}>LAST SEEN</Text><Text style={[s.intelColHead,{width:82}]}>RELATIONSHIP</Text><Text style={[s.intelColHead,{width:82}]}>CONFIDENCE</Text></View>{visible.map((row: any) => <Pressable accessibilityRole="button" accessibilityLabel={`View details for ${row.name}`} onPress={() => setSelectedCharacter(row)} key={row.name} style={({ pressed }) => [s.intelRow, pressed && { backgroundColor: C.coal }]}><View style={{flex:1.3}}><Text style={s.intelName}>{row.name}</Text><Text numberOfLines={2} style={s.intelDetail}>{row.role}</Text></View><View style={{flex:1.1}}><Text style={s.intelValue}>{row.location}</Text><Text style={s.intelDetail}>{row.status}</Text></View><Text style={[s.intelValue,{flex:1}]}>{row.seen}</Text><View style={{width:82}}>{relationshipBadge(row.relationship)}</View><View style={{width:82}}>{confidence(row.level)}</View></Pressable>)}</View>}
    {tab === 'factions' && <View style={s.intelCards}>{visible.map((faction: any) => <View key={faction.id} style={s.intelCard}><Text style={s.intelName}>{faction.name}</Text><Text style={s.copy}>{faction.description}</Text><Text style={s.intelDetail}>Disposition and resources remain estimates until learned in play.</Text></View>)}</View>}
    {tab === 'locations' && <View style={s.intelCards}>{visible.map((location: any) => <View key={location.id} style={s.intelCard}><View style={s.row}><Text style={s.intelName}>{location.name}</Text>{confidence(location.id === campaign.state.locationId ? 'CONFIRMED' : 'MEDIUM')}</View><Text style={s.copy}>{location.public_description || location.description}</Text><Text style={s.intelDetail}>{location.id === campaign.state.locationId ? 'Current location · exact details known' : `${location.location_type || 'Unknown'} knowledge · details may be incomplete`}</Text></View>)}</View>}
    {tab === 'resources' && <View style={s.intelCards}>{visible.map((item: any) => typeof item === 'string' ? <View key={item} style={s.resourceLine}><Ionicons name="diamond-outline" size={15} color={C.gold} /><Text style={s.intelValue}>{item}</Text><Text style={s.resourceKnown}>KNOWN</Text></View> : <View key={item.id} style={s.intelCard}><View style={s.row}><View><Text style={s.intelName}>{item.name}</Text><Text style={s.intelDetail}>{String(item.account_type).toUpperCase()} · controlled by {item.controller_name}</Text></View><Tag>{String(item.status).toUpperCase()}</Tag></View><View style={s.financeGrid}><View><Text style={s.label}>BALANCE</Text><Text style={s.financeBalance}>{money(item.balance, item.currency)}</Text></View><View><Text style={s.label}>RECURRING INCOME</Text><Text style={s.financePositive}>+{money(item.recurring_income, item.currency)}</Text></View><View><Text style={s.label}>RECURRING OUTGOINGS</Text><Text style={s.financeNegative}>−{money(item.recurring_outgoings, item.currency)}</Text></View><View><Text style={s.label}>NET POSITION</Text><Text style={Number(item.recurring_income) - Number(item.recurring_outgoings) >= 0 ? s.financePositive : s.financeNegative}>{money(Number(item.recurring_income) - Number(item.recurring_outgoings), item.currency)}</Text></View>{item.morale != null && <View><Text style={s.label}>MORALE</Text><Text style={s.intelValue}>{item.morale}/100</Text></View>}</View>{(remoteDb?.resourceTransactions || []).filter((entry: any) => entry.account_id === item.id).slice(0, 5).map((entry: any) => <View key={entry.id} style={s.resourceTransaction}><View style={{ flex: 1 }}><Text style={s.intelValue}>{entry.reason}</Text><Text style={s.intelDetail}>{entry.world_date || new Date(entry.created_at).toLocaleDateString()}{entry.counterparty ? ` · ${entry.counterparty}` : ''}</Text></View><Text style={Number(entry.amount) >= 0 ? s.financePositive : s.financeNegative}>{Number(entry.amount) > 0 ? '+' : ''}{money(entry.amount, item.currency)}</Text></View>)}</View>)}</View>}
    {tab === 'chapters' && <View style={s.intelCards}>{visible.map((chapter: any) => <Pressable key={chapter.id} onPress={() => setSelectedChapter(chapter)} style={({ pressed }) => [s.chapterListCard, pressed && { backgroundColor: C.coal }]}><View style={s.chapterNumber}><Text style={s.chapterNumberText}>{chapter.chapter_number}</Text></View><View style={{ flex: 1 }}><Text style={s.intelName}>{chapter.title || `Chapter ${chapter.chapter_number}`}</Text><Text numberOfLines={2} style={s.copy}>{chapter.summary}</Text><Text style={s.intelDetail}>{chapter.transition_reason || `Completed through turn ${chapter.through_turn}`}</Text></View><Ionicons name="chevron-forward" size={20} color={C.gold} /></Pressable>)}</View>}
    {pager}
  </ScrollView></SafeAreaView>;
}

function Packs({ data, startWorld, openBuilder, importPack, deleteWorld }: { data: AppData; startWorld: (p: WorldPack) => void; openBuilder: () => void; importPack: (p: WorldPack) => Promise<{ pack: WorldPack; cost: number }>; deleteWorld: (p: WorldPack) => Promise<void> }) {
  const [report, setReport] = useState<string[]>([]); const [page, setPage] = useState(1); const [pendingDelete, setPendingDelete] = useState<WorldPack | null>(null); const [pendingImport, setPendingImport] = useState<WorldPack | null>(null); const [importing, setImporting] = useState(false); const [deleting, setDeleting] = useState(false); const [deleteError, setDeleteError] = useState(''); const pageSize = 6;
  const custom = [...data.packs.filter(pack => pack.ownerId !== 'system').reduce((latest, pack) => { const current = latest.get(pack.id); if (!current || pack.version > current.version) latest.set(pack.id, pack); return latest; }, new Map<string, WorldPack>()).values()].sort((a, b) => a.metadata.title.localeCompare(b.metadata.title));
  const pageCount = Math.max(1, Math.ceil(custom.length / pageSize)); const safePage = Math.min(page, pageCount); const visibleCustom = custom.slice((safePage - 1) * pageSize, safePage * pageSize);
  const pick = async () => { try { const result = await DocumentPicker.getDocumentAsync({ type: ['application/json', 'text/plain', 'text/markdown'], copyToCacheDirectory: true }); if (result.canceled) return; const asset = result.assets[0]; if (asset.size && asset.size > 500_000) return setReport(['Pack exceeds the 500 KB limit.']); const raw = await (await fetch(asset.uri)).text(); if (!asset.name.endsWith('.json')) return setReport(['Markdown template import is documented and reserved for the server parser. Upload the JSON form of the template in this local build.']); const parsed = JSON.parse(raw); parsed.ownerId = data.user?.id; parsed.status = 'ready'; const resultV = validatePack(parsed); if (!resultV.valid || !resultV.pack) setReport(resultV.errors); else { setReport(resultV.warnings); setPendingImport(resultV.pack); } } catch (e) { setReport([e instanceof Error ? e.message : 'Could not read this pack.']); } };
  return <><ScrollView contentContainerStyle={s.page}><SectionTitle eyebrow="PRIVATE LIBRARY" title="Your worlds" copy="Build a setting from guided fields or import a pack generated from the published template." /><View style={s.actions}><Button label="Create a world" icon="add" onPress={openBuilder} /><Button label="Import .json / .md" icon="cloud-upload-outline" kind="ghost" onPress={pick} /></View>{report.map((x, i) => <Text key={i} style={x.includes('saved') ? s.success : s.error}>{x}</Text>)}
    <View style={s.packCard}><View style={s.packIcon}><Ionicons name="bonfire-outline" size={28} color={C.gold} /></View><View style={{ flex: 1, gap: 5 }}><View style={s.row}><Text style={s.cardTitle}>{defaultWorld.metadata.title}</Text><Tag>OFFICIAL</Tag></View><Text style={s.copy}>{defaultWorld.metadata.description}</Text><Pressable onPress={() => startWorld(defaultWorld)}><Text style={s.goldText}>Start a campaign →</Text></Pressable></View></View>
    {visibleCustom.map(p => <View key={`${p.id}-${p.version}`} style={s.packCard}><View style={s.packIcon}><Ionicons name="map-outline" size={28} color={C.gold} /></View><View style={{ flex: 1, gap: 5 }}><View style={s.row}><View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', flexWrap: 'wrap', gap: 9 }}><Text style={s.cardTitle}>{p.metadata.title}</Text><Tag>{`PRIVATE · V${p.version}`}</Tag></View><Pressable accessibilityRole="button" accessibilityLabel={`Delete ${p.metadata.title}`} onPress={() => setPendingDelete(p)} style={s.deleteCampaignButton}><Ionicons name="trash-outline" size={17} color="#E28B84" /></Pressable></View><Text style={s.copy}>{p.metadata.description}</Text><Pressable onPress={() => startWorld(p)}><Text style={s.goldText}>Start a campaign →</Text></Pressable></View></View>)}
    {custom.length > pageSize && <View style={s.pagination}><Pressable accessibilityRole="button" accessibilityLabel="Previous private worlds page" disabled={safePage === 1} onPress={() => setPage(value => Math.max(1, value - 1))} style={[s.pageButton, safePage === 1 && { opacity: .35 }]}><Ionicons name="chevron-back" size={16} color={C.gold} /><Text style={s.goldText}>Previous</Text></Pressable><Text style={s.muted}>{`Page ${safePage} of ${pageCount}`}</Text><Pressable accessibilityRole="button" accessibilityLabel="Next private worlds page" disabled={safePage === pageCount} onPress={() => setPage(value => Math.min(pageCount, value + 1))} style={[s.pageButton, safePage === pageCount && { opacity: .35 }]}><Text style={s.goldText}>Next</Text><Ionicons name="chevron-forward" size={16} color={C.gold} /></Pressable></View>}
    <View style={s.templateBox}><Ionicons name="document-text-outline" size={24} color={C.gold} /><View style={{ flex: 1 }}><Text style={s.noticeTitle}>Pack author template</Text><Text style={s.copy}>The project includes Markdown and JSON Schema templates for AI-assisted pack creation.</Text></View></View>
  </ScrollView><ConfirmDialog visible={!!pendingImport} title="Import this private world?" body={pendingImport ? `“${pendingImport.metadata.title}” has passed validation. Importing this ${Math.ceil(new TextEncoder().encode(JSON.stringify(pendingImport)).length / 1000)} KB pack costs ${estimatePackImportTurns(pendingImport)} turns. You currently have ${data.user?.turnsRemaining || 0} turns. Failed imports are not charged.` : ''} confirmLabel={importing ? 'Importing…' : `Import for ${pendingImport ? estimatePackImportTurns(pendingImport) : 0} turns`} onCancel={() => !importing && setPendingImport(null)} onConfirm={async () => { if (!pendingImport || importing) return; setImporting(true); try { const saved = await importPack(pendingImport); setPendingImport(null); setReport([`Pack validated and saved privately. ${saved.cost} turn${saved.cost === 1 ? '' : 's'} charged.`]); } catch (error) { setPendingImport(null); setReport([error instanceof Error ? error.message : 'The world could not be imported. No turns were charged.']); } finally { setImporting(false); } }} /><ConfirmDialog visible={!!pendingDelete} title="Delete this private world?" body={pendingDelete ? `“${pendingDelete.metadata.title}” and every saved version of it will be permanently deleted. Any campaigns using this world must be deleted first.` : ''} confirmLabel={deleting ? 'Deleting…' : 'Delete world'} danger onCancel={() => !deleting && setPendingDelete(null)} onConfirm={async () => { if (!pendingDelete || deleting) return; setDeleting(true); try { await deleteWorld(pendingDelete); setPendingDelete(null); } catch (error) { setPendingDelete(null); setDeleteError(error instanceof Error ? error.message : 'The world could not be deleted. Please try again.'); } finally { setDeleting(false); } }} /><WorldDeleteErrorDialog error={deleteError} onClose={() => setDeleteError('')} /></>;
}

function Builder({ userId, onBack, onSave }: { userId: string; onBack: () => void; onSave: (p: WorldPack) => void }) {
  const [title, setTitle] = useState(''); const [tagline, setTagline] = useState(''); const [description, setDescription] = useState(''); const [premise, setPremise] = useState('');
  const field = (label: string, value: string, setter: (v: string) => void, placeholder: string, multiline = false) => <View style={{ gap: 7 }}><Text style={s.label}>{label}</Text><TextInput value={value} onChangeText={setter} placeholder={placeholder} placeholderTextColor="#687074" multiline={multiline} style={[s.input, multiline && { height: 100, textAlignVertical: 'top' }]} /></View>;
  const save = () => { const id = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || uid('world'); const seed = (id2: string, name: string): NamedEntry => ({ id: id2, name, description: `A defining element of ${title} with enough detail to guide the game master.` }); const p: WorldPack = { ...defaultWorld, id, version: 1, ownerId: userId, status: 'ready', metadata: { ...defaultWorld.metadata, title, tagline, author: 'Private creator', description }, premise, factions: [seed('first-power', 'The First Power'), seed('rival-power', 'The Rival Power')], locations: [seed('starting-place', 'The Starting Place')], cultures: [seed('local-culture', 'The Local Culture')], npcs: [seed('first-contact', 'The First Contact')], secrets: [seed('hidden-truth', 'The Hidden Truth')], scenarioHooks: [seed('opening-hook', 'The Opening Hook')] }; const result = validatePack(p); if (!result.valid || !result.pack) return Alert.alert('Pack needs attention', result.errors.join('\n')); onSave(result.pack); };
  return <ScrollView contentContainerStyle={s.page}><Pressable onPress={onBack} style={s.back}><Ionicons name="arrow-back" size={18} color={C.muted} /><Text style={s.muted}>Worlds</Text></Pressable><SectionTitle eyebrow="GUIDED BUILDER" title="Create a world" copy="Start with the dramatic spine. You can expand the factions, people, and rules in later versions." /><View style={s.formCard}>{field('WORLD TITLE', title, setTitle, 'The Glass Republic')}{field('TAGLINE', tagline, setTagline, 'Every truth has a price.')}{field('DESCRIPTION', description, setDescription, 'What makes this world distinctive?', true)}{field('CENTRAL PREMISE', premise, setPremise, 'What conflict is already in motion?', true)}<Button label="Validate and save privately" icon="shield-checkmark" disabled={title.length < 3 || tagline.length < 3 || description.length < 20 || premise.length < 40} onPress={save} /></View><View style={s.notice}><Ionicons name="git-branch-outline" size={22} color={C.gold} /><View style={{ flex: 1 }}><Text style={s.noticeTitle}>Version-safe by design</Text><Text style={s.copy}>Future edits create a new pack version. Existing campaigns remain pinned to the world they began in.</Text></View></View></ScrollView>;
}

function Settings({ data, logout, reset }: { data: AppData; logout: () => void; reset: (password: string) => Promise<void> }) { const [confirmDelete, setConfirmDelete] = useState(false); const [deleting, setDeleting] = useState(false); const [deleteError, setDeleteError] = useState(''); const [password, setPassword] = useState(''); const close = () => { if (deleting) return; setConfirmDelete(false); setPassword(''); setDeleteError(''); }; const confirm = async () => { if (deleting || password.length < 8) return; setDeleting(true); setDeleteError(''); try { await reset(password); setConfirmDelete(false); setPassword(''); } catch (error) { setDeleteError(error instanceof Error ? error.message : 'Your account could not be deleted. Nothing was changed.'); } finally { setDeleting(false); } }; return <><ScrollView contentContainerStyle={s.page}><SectionTitle eyebrow="ACCOUNT" title={data.user?.name || 'Player'} copy={[data.user?.username ? `@${data.user.username}` : '', data.user?.email].filter(Boolean).join(' · ')} /><View style={s.settingCard}><View style={s.settingRow}><Ionicons name="sparkles-outline" size={20} color={C.gold} /><View style={{ flex: 1 }}><Text style={s.noticeTitle}>AI turn allowance</Text><Text style={s.copy}>{data.user?.turnsRemaining} turns remaining in this prototype.</Text></View></View><View style={s.settingRow}><Ionicons name="shield-checkmark-outline" size={20} color={C.green} /><View style={{ flex: 1 }}><Text style={s.noticeTitle}>Mature content boundary</Text><Text style={s.copy}>Adult consensual relationships can develop naturally, with intimate scenes fading to black. Sexual violence may be acknowledged only as a non-graphic off-screen crime or historical consequence; it is never depicted or offered as a player action.</Text></View></View><View style={s.settingRow}><Ionicons name="lock-closed-outline" size={20} color={C.gold} /><View style={{ flex: 1 }}><Text style={s.noticeTitle}>Private by default</Text><Text style={s.copy}>Your uploaded packs are not listed publicly or used as shared training data.</Text></View></View></View><Button label="Sign out" kind="ghost" icon="log-out-outline" onPress={logout} /><Button label="Delete account" kind="danger" icon="trash-outline" onPress={() => { setDeleteError(''); setPassword(''); setConfirmDelete(true); }} /></ScrollView><AccountDeleteDialog visible={confirmDelete} password={password} error={deleteError} deleting={deleting} onPasswordChange={setPassword} onCancel={close} onConfirm={confirm} /></> }

export default function App() {
  const [data, setData] = useState<AppData>(initialData); const [loaded, setLoaded] = useState(false); const [screen, setScreen] = useState<Screen>('auth'); const [selectedPack, setSelectedPack] = useState<WorldPack>(defaultWorld); const [campaignId, setCampaignId] = useState(''); const [campaignCreateError, setCampaignCreateError] = useState('');
  const passwordRecoveryRef = useRef(hasPasswordRecoveryUrl);
  useEffect(() => { (async () => { try { const initialUrl = await Linking.getInitialURL(); if (initialUrl && /(?:[?#&])type=recovery(?:[&#]|$)/i.test(initialUrl)) passwordRecoveryRef.current = true; const d = isSupabaseConfigured ? await loadRemoteAppData() : await loadData(); if (passwordRecoveryRef.current) { setData(initialData); setScreen('reset-password'); return; } const next = d || initialData; setData(next); setScreen(next.user ? 'home' : 'auth'); } catch (error) { if (passwordRecoveryRef.current) { setData(initialData); setScreen('reset-password'); } else { Alert.alert('Backend connection failed', error instanceof Error ? error.message : 'Could not connect to Supabase.'); setScreen('auth'); } } finally { setLoaded(true); } })(); }, []);
  useEffect(() => { if (!supabase) return; const { data: listener } = supabase.auth.onAuthStateChange(event => { if (event === 'PASSWORD_RECOVERY') { passwordRecoveryRef.current = true; setData(initialData); setLoaded(true); setScreen('reset-password'); } }); return () => listener.subscription.unsubscribe(); }, []);
  useEffect(() => { if (loaded && !isSupabaseConfigured) saveData(data); }, [data, loaded]);
  const campaign = data.campaigns.find(c => c.id === campaignId); const pack = campaign ? data.packs.find(p => p.id === campaign.packId && p.version === campaign.packVersion) || defaultWorld : selectedPack;
  const enter = async (username: string, password: string, action: 'signin' | 'signup', email?: string) => { if (isSupabaseConfigured) { await authenticateUsername(username, password, action, email); const remote = await loadRemoteAppData(); if (!remote) throw new Error('The account session could not be loaded.'); setData(remote); } else { const name = username.replace(/[_-]+/g, ' ').replace(/\b\w/g, letter => letter.toUpperCase()); setData(d => ({ ...d, user: { id: uid('user'), name, username, email, turnsRemaining: 100 } })); } setScreen('home'); };
  const createCampaign = async (character: Character, campaignName: string) => { setCampaignCreateError(''); if (isSupabaseConfigured) { setLoaded(false); try { const id = await createRemoteCampaign(selectedPack, character, campaignName); const remote = await loadRemoteAppData(); if (!remote) throw new Error('The campaign was created but could not be loaded.'); setData(remote); setCampaignId(id); setScreen('play'); } catch (error) { setCampaignCreateError(error instanceof Error ? error.message : 'Please try again.'); } finally { setLoaded(true); } return; } const opening = selectedPack.openingScenario; const startingItem = character.background.id === 'knight' ? 'Mail, Sword, and Warhorse' : character.background.id === 'lord' ? 'Household Seal and Treasury Key' : character.background.id === 'serf' ? 'Work Knife and Mended Cloak' : selectedPack.items[0]?.name || 'Traveler’s kit'; const c: Campaign = { id: uid('campaign'), ownerId: data.user!.id, title: campaignName.trim(), packId: selectedPack.id, packVersion: selectedPack.version, character, state: { locationId: opening?.startLocationId || selectedPack.locations[0].id, health: 100, resolve: 88, inventory: opening?.startingInventory || [startingItem, 'Rain-soaked sealed letter'], relationships: opening?.relationships || {}, memories: opening?.memories || ['A badly wounded male courier handed you a sealed letter before collapsing at your feet.'], unresolvedThreads: opening?.unresolvedThreads || ['Why did the courier choose you?'], summary: opening?.narration.replaceAll('{name}', character.name) || 'The campaign has begun.', sceneFacts: opening?.sceneFacts || [], ...(opening?.calendar ? { campaignDate: { calendarName: opening.calendar.name, year: opening.calendar.year, day: opening.calendar.day, segment: opening.calendar.segment } } : {}) }, turns: [], currentChapter: 1, chapterTitle: opening?.chapterLabel || 'Chapter I', archived: false, updatedAt: new Date().toISOString() }; setData(d => ({ ...d, campaigns: [c, ...d.campaigns] })); setCampaignId(c.id); setScreen('play'); };
  const updateCampaign = (next: Campaign, charge = 0) => setData(d => ({ ...d, campaigns: d.campaigns.map(c => c.id === next.id ? next : c), user: d.user ? { ...d.user, turnsRemaining: Math.max(0, d.user.turnsRemaining - charge) } : null }));
  if (!loaded) return <View style={s.loading}><ActivityIndicator color={C.gold} /><Text style={s.muted}>Opening the chronicle…</Text></View>;
  if (screen === 'auth') return <Auth onEnter={enter} />;
  if (screen === 'reset-password') return <ResetPassword onComplete={() => { setData(initialData); setScreen('auth'); Alert.alert('Password updated', 'Your password has been changed. Sign in with your username and new password.'); }} />;
  if (screen === 'character') return <SafeAreaView style={s.root}><CharacterCreate pack={selectedPack} onBack={() => setScreen('packs')} onCreate={createCampaign} /><CampaignCreateErrorDialog error={campaignCreateError} onClose={() => setCampaignCreateError('')} /></SafeAreaView>;
  if (screen === 'play' && campaign) return <Play campaign={campaign} pack={pack} updateCampaign={updateCampaign} onExit={() => setScreen('home')} onOpenIntel={() => setScreen('intel')} />;
  if (screen === 'intel' && campaign) return <WorldIntel campaign={campaign} pack={pack} onBack={() => setScreen('play')} />;
  if (screen === 'builder') return <SafeAreaView style={s.root}><Builder userId={data.user!.id} onBack={() => setScreen('packs')} onSave={p => { setData(d => ({ ...d, packs: [...d.packs, p] })); setScreen('packs'); }} /></SafeAreaView>;
  const content = screen === 'home' ? <Home data={data} openCampaign={c => { setCampaignId(c.id); setScreen('play'); }} deleteCampaign={async c => { if (isSupabaseConfigured) await deleteRemoteCampaign(c.id); setData(current => ({ ...current, campaigns: current.campaigns.filter(item => item.id !== c.id) })); if (campaignId === c.id) setCampaignId(''); }} openWorlds={() => setScreen('packs')} openStore={() => setScreen('store')} /> : screen === 'store' ? <Store balance={data.user?.turnsRemaining || 0} onBack={() => setScreen('home')} onPurchase={turns => { setData(d => ({ ...d, user: d.user ? { ...d.user, turnsRemaining: d.user.turnsRemaining + turns } : null })); Alert.alert('Turns added', `${turns} demonstration turns were added to your balance.`); setScreen('home'); }} /> : screen === 'packs' ? <Packs data={data} startWorld={p => { setSelectedPack(p); setScreen('character'); }} openBuilder={() => setScreen('builder')} importPack={async p => { if (isSupabaseConfigured) { const result = await saveRemoteWorldPack(p); setData(d => ({ ...d, packs: [...d.packs.filter(x => !(x.id === result.pack.id && x.version === result.pack.version)), result.pack], user: d.user ? { ...d.user, turnsRemaining: result.turnsRemaining } : null })); return { pack: result.pack, cost: result.cost }; } const cost = estimatePackImportTurns(p); if (!data.user || data.user.turnsRemaining < cost) throw new Error(`You need ${cost} turns to import this world.`); setData(d => ({ ...d, packs: [...d.packs, p], user: d.user ? { ...d.user, turnsRemaining: d.user.turnsRemaining - cost } : null })); return { pack: p, cost }; }} deleteWorld={async p => { if (isSupabaseConfigured) await deleteRemoteWorldPack(p); setData(d => ({ ...d, packs: d.packs.filter(world => world.id !== p.id) })); }} /> : <Settings data={data} logout={async () => { if (isSupabaseConfigured) await signOutRemote(); setData(initialData); setScreen('auth'); }} reset={async password => { if (isSupabaseConfigured) await deleteRemoteAccount(password); await clearData(); setData(initialData); setScreen('auth'); }} />;
  return <SafeAreaView style={s.root}><View style={s.shell}>{content}<Nav screen={screen} setScreen={setScreen} /></View></SafeAreaView>;
}

